package com.parvnigam.careerbridge;
import java.net.*;
import java.net.http.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.security.oauth2.jwt.JwtEncoder;
import org.springframework.mail.javamail.JavaMailSender;
import org.springframework.web.server.ResponseStatusException;
import tools.jackson.databind.json.JsonMapper;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"spring.datasource.url=jdbc:h2:mem:emailtests;MODE=PostgreSQL;DB_CLOSE_DELAY=-1","spring.jpa.hibernate.ddl-auto=create-drop","app.local-email-testing=true","app.local-inbox-port=0","app.mail-enabled=false","app.redis-enabled=false"})
class EmailVerificationTests {
 @LocalServerPort int port;@Autowired VerificationMail mail;@Autowired Repositories.Accounts accounts;@Autowired JwtEncoder encoder;@Autowired EmailVerification verification;
 final HttpClient http=HttpClient.newHttpClient();final JsonMapper json=JsonMapper.builder().build();
 HttpResponse<String> call(String path,String jwt,Object body)throws Exception{var b=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api"+path));if(jwt!=null)b.header("Authorization","Bearer "+jwt);if(body!=null)b.header("Content-Type","application/json");return http.send(b.method(body==null?"GET":"POST",body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body))).build(),HttpResponse.BodyHandlers.ofString());}
 String signup(String role)throws Exception{String email=UUID.randomUUID()+"@example.com";Map<String,Object> d=new HashMap<>(Map.of("name","Email Tester","email",email,"password","Strong@12345","role",role));if(role.equals("STUDENT"))d.put("universityId",json.readTree(call("/public/universities",null,null).body()).get(0).get("id").asLong());var result=call("/auth/register",null,d);assertEquals(201,result.statusCode(),result.body());assertFalse(result.body().contains("token"));assertFalse(result.body().contains("verificationHash"));return email;}
 String link(String email){synchronized(mail.messages){return mail.messages.stream().filter(m->m.to().equals(email)).reduce((a,b)->b).orElseThrow().link();}}
 String token(String email){return link(email).split("#token=")[1];}
 HttpResponse<String> verify(String token)throws Exception{return call("/auth/verify-email",null,Map.of("token",token));}
 HttpResponse<String> login(String email)throws Exception{return call("/auth/login",null,Map.of("email",email,"password","Strong@12345"));}
 @Test void studentMustVerifyAndTokenIsSingleUse()throws Exception{String email=signup("STUDENT"),token=token(email);Model.Account a=accounts.findByEmail(email).orElseThrow();assertEquals(EmailVerification.hash(token),a.verificationHash);assertNotEquals(token,a.verificationHash);assertEquals(403,login(email).statusCode());String forged=SecurityConfig.token(encoder,a);assertEquals(401,call("/auth/me",forged,null).statusCode());assertEquals(403,call("/student/profile",forged,null).statusCode());assertEquals(200,verify(token).statusCode());assertEquals(400,verify(token).statusCode());a=accounts.findByEmail(email).orElseThrow();assertTrue(a.emailVerified);assertNull(a.verificationHash);assertNotNull(a.emailVerifiedAt);assertEquals(200,login(email).statusCode());String jwt=json.readTree(login(email).body()).get("token").asText();assertEquals(200,call("/student/profile",jwt,null).statusCode());}
 @Test void expiryAndResendInvalidateOldLink()throws Exception{String email=signup("RECRUITER"),old=token(email);Model.Account a=accounts.findByEmail(email).orElseThrow();a.verificationExpiresAt=Instant.now().minusSeconds(1);a.verificationSentAt=Instant.now().minusSeconds(61);accounts.save(a);assertEquals(400,verify(old).statusCode());assertEquals(200,call("/auth/resend-verification",null,Map.of("email",email)).statusCode());String replacement=token(email);assertNotEquals(old,replacement);assertEquals(400,verify(old).statusCode());assertEquals(200,verify(replacement).statusCode());assertEquals(200,login(email).statusCode());}
 @Test void resendIsGenericAndThrottled()throws Exception{String email=signup("RECRUITER"),original=token(email);var known=call("/auth/resend-verification",null,Map.of("email",email));var unknown=call("/auth/resend-verification",null,Map.of("email","absent@example.com"));assertEquals(known.body(),unknown.body());assertEquals(original,token(email));for(int i=0;i<10;i++)verification.limit("test-resend-ip","resend");assertEquals(429,assertThrows(ResponseStatusException.class,()->verification.limit("test-resend-ip","resend")).getStatusCode().value());}
 @Test void invalidAndDisabledAccountLinksFail()throws Exception{assertEquals(400,verify("bad").statusCode());assertEquals(400,verify("A".repeat(43)).statusCode());String email=signup("RECRUITER"),token=token(email);Model.Account a=accounts.findByEmail(email).orElseThrow();a.enabled=false;accounts.save(a);assertEquals(400,verify(token).statusCode());assertEquals(401,login(email).statusCode());}
 @Test void concurrentConsumptionAllowsOneSuccess()throws Exception{String email=signup("RECRUITER"),token=token(email);var pool=Executors.newFixedThreadPool(2);try{var start=new CountDownLatch(1);Callable<Integer> task=()->{start.await();return verify(token).statusCode();};var a=pool.submit(task);var b=pool.submit(task);start.countDown();List<Integer> codes=new ArrayList<>(List.of(a.get(),b.get()));Collections.sort(codes);assertEquals(List.of(200,400),codes);}finally{pool.shutdownNow();}}
 @Test void localInboxIsLoopbackOnlyAndEscapesHtml()throws Exception{assertEquals("127.0.0.1",mail.inbox.getAddress().getAddress().getHostAddress());mail.send("<script>@example.com","http://localhost:5173/verify-email#token=test",24);var r=http.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+mail.inbox.getAddress().getPort()+"/")).GET().build(),HttpResponse.BodyHandlers.ofString());assertEquals(200,r.statusCode());assertTrue(r.body().contains("&lt;script&gt;"));assertEquals("no-store",r.headers().firstValue("Cache-Control").orElseThrow());assertEquals(403,http.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+mail.inbox.getAddress().getPort()+"/")).POST(HttpRequest.BodyPublishers.noBody()).build(),HttpResponse.BodyHandlers.ofString()).statusCode());}
 @Test void smtpFailuresAreReportedWithoutSecrets()throws Exception{JavaMailSender sender=mock(JavaMailSender.class);{var disabled=new VerificationMail(sender,false,false,"sender@example.com",0);assertEquals(503,assertThrows(ResponseStatusException.class,()->disabled.send("to@example.com","secret-link",24)).getStatusCode().value());var real=new VerificationMail(sender,false,true,"sender@example.com",0);doThrow(new RuntimeException("private SMTP detail")).when(sender).send(any(org.springframework.mail.SimpleMailMessage.class));var e=assertThrows(ResponseStatusException.class,()->real.send("to@example.com","secret-link",24));assertEquals(503,e.getStatusCode().value());assertFalse(e.getReason().contains("private"));}}
}
